---SetGiftSkillInfo
---@param vo TalentVo
---@param skillLv number
function UIBattlingSkillCardSkillInfoNode:SetGiftSkillInfo(skillId, skillLv, roleId, vo)
    -- base.SetSkillCardInfo(self, { roleId = roleId, skillId = skillId,  star = skillLv, skillLv = skillLv })  -- 现在的被动技能卡不需要这个了
    local icon = self.controller.transform:Find("Img_GiftIcon")
    if IsNull(icon) then return end
    local iaIcon = KTool.GetOrAddComponent(icon.gameObject, typeof(CS.Engine.UI.ImageAlterable))
    ---@type TalentVo
    self.dataVo = vo
    iaIcon:LoadSprite(vo.iconPath)
    local RT_LevelRoot = self.controller.transform:Find("Level")
    local txtLv = self.controller.transform:Find("Level/TextNumber")
    if not IsNull(txtLv) and isNotNull(skillLv) then
        KTool.SetActive(RT_LevelRoot, true)
        local tmLv = KTool.GetOrAddComponent(txtLv.gameObject, typeof(CS.TMPro.TextMeshProUGUI))
        tmLv.text = string.format("<size=30>Lv</size>.%02d", skillLv)
    end
end

return UIBattlingSkillCardSkillInfoNode